1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件保护“打开本地数据”时对已保存判定结论的完整性校验：
14	// 只有原测量项目与逐项判定按项目名完整一一对应、且对应项目的测量值一致时，
15	// 已确认样品才能被读入；缺项、多项、项目重复、测量值对不上（零也是合法
16	// 测量值）或整份样品没有测量项目，都必须让整次 Open 失败，返回 nil 存放，
17	// 错误信息点到具体样品编号与项目，且不覆盖原文件、不静默跳过、不补判定、
18	// 不改成待判定。待判定样品、待判定后作废（无历史依据）的样品不受影响；
19	// 已确认后作废但历史依据完整的样品继续兼容。
20	
21	const (
22		openPH   = "pH"
23		openTurb = "浊度"
24	)
25	
26	func openEff() time.Time { return at(1, 0) }
27	
28	// writeDiskFile 手工写入一份数据文件，便于构造正常流程不会产生的损坏记录。
29	func writeDiskFile(t *testing.T, dir string, st diskState) {
30		t.Helper()
31		data, err := json.MarshalIndent(st, "", "  ")
32		if err != nil {
33			t.Fatalf("marshal data file: %v", err)
34		}
35		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
36			t.Fatalf("write data file: %v", err)
37		}
38	}
39	
40	func openPoints() map[string]SamplingPoint {
41		return map[string]SamplingPoint{"P1": {ID: "P1", Name: "一号取水口"}}
42	}
43	
44	// phTurbResults 是与 pH 9、浊度 4 的原测量完整对应的两条判定，
45	// 排列顺序故意与测量相反，用来证明按项目名对应而非按位置对应。
46	func phTurbResults() []ItemResult {
47		return []ItemResult{
48			{Item: openTurb, Value: 4, Limit: 4, LimitEffective: openEff(), Exceeded: false},
49			{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
50		}
51	}
52	
53	func phTurbMeasurements() []Measurement {
54		return []Measurement{
55			{Item: openPH, Value: 9},
56			{Item: openTurb, Value: 4},
57		}
58	}
59	
60	// assertOpenRejects 断言打开整次失败：返回 nil 存放、错误可识别为
61	// ErrCorruptRecord，且信息包含出问题的样品编号与项目（noItem 为 true 时
62	// 只要求编号），原文件字节不被改动。
63	func assertOpenRejects(t *testing.T, dir, sampleID, itemHint string, noItem bool) {
64		t.Helper()
65		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
66		if err != nil {
67			t.Fatalf("read file before open: %v", err)
68		}
69		got, err := Open(dir)
70		if err == nil {
71			if got != nil {
72				got.Close()
73			}
74			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
75		}
76		if got != nil {
77			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
78		}
79		if !errors.Is(err, ErrCorruptRecord) {
80			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
81		}
82		msg := err.Error()
83		if !strings.Contains(msg, sampleID) {
84			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
85		}
86		if !noItem && itemHint != "" && !strings.Contains(msg, itemHint) {
87			t.Fatalf("错误信息应指出项目 %q，实际 %q", itemHint, msg)
88		}
89		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
90		if rerr != nil {
91			t.Fatalf("read file after open: %v", rerr)
92		}
93		if string(after) != string(before) {
94			t.Fatalf("打开失败不得覆盖或改写原数据文件")
95		}
96	}
97	
98	// 已确认样品只剩一个项目的判定依据（浊度缺失）：即使整份超标标记还在，
99	// 也不能凭该标记返回达标或超标，整次打开失败并点名样品与缺失项目。
100	func TestOpenConfirmedMissingItemResult(t *testing.T) {
101		dir := t.TempDir()
102		writeDiskFile(t, dir, diskState{
103			Points: openPoints(),
104			Samples: map[string]*Sample{
105				"S1": {
106					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
107					Measurements: phTurbMeasurements(),
108					Status:       StatusConfirmed, Exceeded: true,
109					Results: []ItemResult{
110						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
111					},
112				},
113			},
114		})
115		assertOpenRejects(t, dir, "S1", openTurb, false)
116	}
117	
118	// 两条判定都在，但浊度判定里的测量值写成了 3（原测量是 4）：
119	// 项目名称相同也不能接受来自另一份记录的测量值，整次打开失败。
120	func TestOpenConfirmedMismatchedValue(t *testing.T) {
121		dir := t.TempDir()
122		results := phTurbResults()
123		results[0].Value = 3 // 浊度 4 被写成 3
124		writeDiskFile(t, dir, diskState{
125			Points: openPoints(),
126			Samples: map[string]*Sample{
127				"S1": {
128					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
129					Measurements: phTurbMeasurements(),
130					Status:       StatusConfirmed, Exceeded: false,
131					Results: results,
132				},
133			},
134		})
135		assertOpenRejects(t, dir, "S1", openTurb, false)
136	}
137	
138	// 零是合法测量值：原测量与判定都是零时必须正常读入；只有判定值被改成
139	// 非零（对不上）时才拒绝，不能把零当成没有填写。
140	func TestOpenConfirmedZeroValueIsValid(t *testing.T) {
141		dir := t.TempDir()
142		zeroResults := []ItemResult{
143			{Item: openTurb, Value: 0, Limit: 4, LimitEffective: openEff(), Exceeded: false},
144			{Item: openPH, Value: 0, Limit: 8, LimitEffective: openEff(), Exceeded: false},
145		}
146	
147		// 完整且为零：成功读入，零值原样保留。
148		writeDiskFile(t, dir, diskState{
149			Points: openPoints(),
150			Samples: map[string]*Sample{
151				"S1": {
152					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
153					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
154					Status:       StatusConfirmed, Exceeded: false,
155					Results: zeroResults,
156				},
157			},
158		})
159		s, err := Open(dir)
160		if err != nil {
161			t.Fatalf("零是合法测量值，完整记录应正常读入: %v", err)
162		}
163		list, err := s.ListByPoint("P1")
164		if err != nil || len(list) != 1 {
165			t.Fatalf("ListByPoint: %+v err=%v", list, err)
166		}
167		ms := map[string]float64{}
168		for _, m := range list[0].Measurements {
169			ms[m.Item] = m.Value
170		}
171		if ms[openPH] != 0 || ms[openTurb] != 0 {
172			t.Fatalf("零测量值必须原样保留: %+v", list[0].Measurements)
173		}
174		if err := s.Close(); err != nil {
175			t.Fatalf("Close: %v", err)
176		}
177	
178		// 判定把零改成 1：对不上，整次失败；错误仍点名该项目。
179		bad := []ItemResult{
180			zeroResults[0],
181			{Item: openPH, Value: 1, Limit: 8, LimitEffective: openEff(), Exceeded: false},
182		}
183		writeDiskFile(t, dir, diskState{
184			Points: openPoints(),
185			Samples: map[string]*Sample{
186				"S1": {
187					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
188					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
189					Status:       StatusConfirmed, Exceeded: false,
190					Results: bad,
191				},
192			},
193		})
194		assertOpenRejects(t, dir, "S1", openPH, false)
195	}
196	
197	// 同一项目在原测量里出现两次，是记录有误：整次打开失败。
198	func TestOpenConfirmedDuplicateMeasurement(t *testing.T) {
199		dir := t.TempDir()
200		writeDiskFile(t, dir, diskState{
201			Points: openPoints(),
202			Samples: map[string]*Sample{
203				"S1": {
204					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
205					Measurements: []Measurement{
206						{Item: openPH, Value: 9}, {Item: openPH, Value: 7},
207					},
208					Status: StatusConfirmed, Exceeded: true,
209					Results: []ItemResult{
210						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
211					},
212				},
213			},
214		})
215		assertOpenRejects(t, dir, "S1", openPH, false)
216	}
217	
218	// 同一项目在判定中出现两次，同样是记录有误：整次打开失败。
219	func TestOpenConfirmedDuplicateResult(t *testing.T) {
220		dir := t.TempDir()
221		writeDiskFile(t, dir, diskState{
222			Points: openPoints(),
223			Samples: map[string]*Sample{
224				"S1": {
225					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
226					Measurements: []Measurement{{Item: openPH, Value: 9}},
227					Status:       StatusConfirmed, Exceeded: true,
228					Results: []ItemResult{
229						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
230						{Item: openPH, Value: 9, Limit: 6, LimitEffective: openEff(), Exceeded: true},
231					},
232				},
233			},
234		})
235		assertOpenRejects(t, dir, "S1", openPH, false)
