238	// 判定中出现原测量没有的项目：整次打开失败并点名多出的项目。
239	func TestOpenConfirmedExtraResultItem(t *testing.T) {
240		dir := t.TempDir()
241		writeDiskFile(t, dir, diskState{
242			Points: openPoints(),
243			Samples: map[string]*Sample{
244				"S1": {
245					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
246					Measurements: []Measurement{{Item: openPH, Value: 9}},
247					Status:       StatusConfirmed, Exceeded: true,
248					Results: []ItemResult{
249						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
250						{Item: "COD", Value: 1, Limit: 30, LimitEffective: openEff(), Exceeded: false},
251					},
252				},
253			},
254		})
255		assertOpenRejects(t, dir, "S1", "COD", false)
256	}
257	
258	// 已确认样品一个测量项目都没有时也要失败，错误指出是哪份样品。
259	func TestOpenConfirmedNoMeasurements(t *testing.T) {
260		dir := t.TempDir()
261		writeDiskFile(t, dir, diskState{
262			Points: openPoints(),
263			Samples: map[string]*Sample{
264				"S1": {
265					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
266					Status: StatusConfirmed, Exceeded: false,
267					Results: nil,
268				},
269			},
270		})
271		assertOpenRejects(t, dir, "S1", "", true)
272	}
273	
274	// 一个文件里其他样品正常，也不能静默跳过有问题的样品继续打开：
275	// 整次失败、无可用存放，正常样品也读不到。
276	func TestOpenOneBadSampleRejectsWholeFile(t *testing.T) {
277		dir := t.TempDir()
278		writeDiskFile(t, dir, diskState{
279			Points: openPoints(),
280			Samples: map[string]*Sample{
281				// 完整、正常的已确认样品。
282				"S-GOOD": {
283					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
284					Measurements: []Measurement{{Item: openPH, Value: 7}},
285					Status:       StatusConfirmed, Exceeded: false,
286					Results: []ItemResult{
287						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
288					},
289				},
290				// 缺浊度判定的损坏样品。
291				"S-BAD": {
292					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
293					Measurements: phTurbMeasurements(),
294					Status:       StatusConfirmed, Exceeded: true,
295					Results: []ItemResult{
296						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
297					},
298				},
299			},
300		})
301		assertOpenRejects(t, dir, "S-BAD", openTurb, false)
302	}
303	
304	// 完整记录按项目名对应：两个列表排列顺序不同不影响读入；读入后测量与判定
305	// 仍各自保留原有顺序，已保存的上限、生效时间、逐项结论与整份超标标记原样保留。
306	func TestOpenCompleteRecordOrderPreserved(t *testing.T) {
307		dir := t.TempDir()
308		wantMeas := phTurbMeasurements() // pH 在前、浊度在后
309		wantResults := phTurbResults()   // 浊度在前、pH 在后（故意相反）
310		writeDiskFile(t, dir, diskState{
311			Points: openPoints(),
312			Samples: map[string]*Sample{
313				"S1": {
314					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
315					Measurements: wantMeas,
316					Status:       StatusConfirmed, Exceeded: true,
317					Results: wantResults,
318				},
319			},
320		})
321		s, err := Open(dir)
322		if err != nil {
323			t.Fatalf("完整记录（顺序相反）应正常读入: %v", err)
324		}
325		defer s.Close()
326	
327		latest, ok, err := s.LatestResult("P1")
328		if err != nil || !ok || latest.ID != "S1" {
329			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
330		}
331		// 原测量顺序保留。
332		if len(latest.Measurements) != 2 ||
333			latest.Measurements[0].Item != openPH || latest.Measurements[0].Value != 9 ||
334			latest.Measurements[1].Item != openTurb || latest.Measurements[1].Value != 4 {
335			t.Fatalf("原测量顺序必须保留: %+v", latest.Measurements)
336		}
337		// 判定顺序保留。
338		if len(latest.Results) != 2 ||
339			latest.Results[0].Item != openTurb || latest.Results[0].Value != 4 ||
340			latest.Results[1].Item != openPH || latest.Results[1].Value != 9 {
341			t.Fatalf("逐项判定顺序必须保留: %+v", latest.Results)
342		}
343		// 已保存的上限、生效时间、逐项结论与整份超标标记原样保留，不重新计算。
344		turb := latest.Results[0]
345		if turb.Limit != 4 || !turb.LimitEffective.Equal(openEff()) || turb.Exceeded {
346			t.Fatalf("浊度判定依据应原样保留: %+v", turb)
347		}
348		ph := latest.Results[1]
349		if ph.Limit != 8 || !ph.LimitEffective.Equal(openEff()) || !ph.Exceeded {
350			t.Fatalf("pH 判定依据应原样保留: %+v", ph)
351		}
352		if !latest.Exceeded {
353			t.Fatalf("整份超标标记应原样保留为 true")
354		}
355		// 重复确认返回同一份已保存依据。
356		again, err := s.Confirm("S1")
357		if err != nil {
358			t.Fatalf("重复确认: %v", err)
359		}
360		if len(again.Results) != 2 || again.Results[0].Item != openTurb ||
361			again.Results[1].Item != openPH || !again.Exceeded {
362			t.Fatalf("重复确认应返回原保存依据: %+v", again.Results)
363		}
364	}
365	
366	// 后来新增或补录的限值即使会改变重新判定的结果，也不能据此拒绝完整记录，
367	// 更不能在打开时重算结论：已保存的上限、生效时间与超标结论保持原样。
368	func TestOpenCompleteRecordUnaffectedByNewerLimits(t *testing.T) {
369		s, dir := open(t)
370		mustPoint(t, s, "P1", "一号取水口")
371		mustLimit(t, s, "P1", openPH, 8.0, openEff())
372		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
373		conf, err := s.Confirm("S1")
374		if err != nil || !conf.Exceeded || conf.Results[0].Limit != 8.0 {
375			t.Fatalf("setup: 9 > 8 应超标: %+v err=%v", conf, err)
376		}
377		if err := s.Close(); err != nil {
378			t.Fatalf("Close: %v", err)
379		}
380	
381		// 补录一版采样时刻之后才生效、更宽松的限值；再补一版采样之前生效的
382		// 宽松限值（若重算就会变成达标）。
383		s2, err := Open(dir)
384		if err != nil {
385			t.Fatalf("reopen for backfill: %v", err)
386		}
387		mustLimit(t, s2, "P1", openPH, 100.0, at(15, 0))
388		mustLimit(t, s2, "P1", openPH, 100.0, at(2, 0))
389		if err := s2.Close(); err != nil {
390			t.Fatalf("Close s2: %v", err)
391		}
392	
393		// 重新打开：完整记录不被新限值拒绝，结论仍是保存时的 8@09-01、超标。
394		s3, err := Open(dir)
395		if err != nil {
396			t.Fatalf("含新增限值时重新打开完整记录不应失败: %v", err)
397		}
398		defer s3.Close()
399		latest, ok, err := s3.LatestResult("P1")
400		if err != nil || !ok {
401			t.Fatalf("最近有效结果: %+v ok=%v err=%v", latest, ok, err)
402		}
403		if !latest.Exceeded || len(latest.Results) != 1 {
404			t.Fatalf("整份结论被重算: %+v", latest)
405		}
406		r := latest.Results[0]
407		if r.Value != 9 || r.Limit != 8.0 || !r.LimitEffective.Equal(openEff()) || !r.Exceeded {
408			t.Fatalf("已保存依据必须原样保留，不能按新限值重算: %+v", r)
409		}
410	}
411	
412	// 待判定样品没有判定记录、待判定后作废的样品没有历史依据，都仍是正常情况；
413	// 已确认后作废但历史依据完整的样品也继续兼容（列表可查、最近结果跳过、
414	// 再确认拒绝）。
415	func TestOpenPendingAndVoidedSamples(t *testing.T) {
416		dir := t.TempDir()
417		writeDiskFile(t, dir, diskState{
418			Points: map[string]SamplingPoint{
419				"P1": {ID: "P1", Name: "一号取水口"},
420				"P2": {ID: "P2", Name: "二号取水口"},
421			},
422			Samples: map[string]*Sample{
423				// 待判定：无判定记录。
424				"SP": {
425					ID: "SP", PointID: "P1", SampledAt: at(2, 0),
426					Measurements: []Measurement{{Item: openPH, Value: 9}},
427					Status:       StatusPending,
428				},
429				// 待判定后作废：无历史依据。
430				"SV": {
431					ID: "SV", PointID: "P1", SampledAt: at(3, 0),
432					Measurements: []Measurement{{Item: openPH, Value: 9}},
433					Status:       StatusVoided, VoidReason: "录入信息有误",
434				},
435				// 已确认后作废：历史依据完整。
436				"SCV": {
437					ID: "SCV", PointID: "P2", SampledAt: at(4, 0),
438					Measurements: []Measurement{{Item: openPH, Value: 9}},
439					Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: true,
440					Results: []ItemResult{
441						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
442					},
443				},
444			},
445		})
446		s, err := Open(dir)
447		if err != nil {
448			t.Fatalf("待判定与无历史依据的作废样品都应正常读入: %v", err)
449		}
450		defer s.Close()
451	
452		p1, err := s.ListByPoint("P1")
453		if err != nil || len(p1) != 2 {
454			t.Fatalf("P1 列表: %+v err=%v", p1, err)
455		}
456		byID := map[string]Sample{}
457		for _, smp := range p1 {
458			byID[smp.ID] = smp
459		}
460		sp := byID["SP"]
461		if sp.Status != StatusPending || sp.Results != nil || sp.Exceeded {
462			t.Fatalf("待判定样品读入后不应带结论: %+v", sp)
463		}
464		sv := byID["SV"]
465		if sv.Status != StatusVoided || sv.VoidReason != "录入信息有误" ||
466			len(sv.Results) != 0 || sv.Exceeded {
467			t.Fatalf("待判定后作废样品不应凭空获得结论: %+v", sv)
468		}
469		// P1 没有已确认且未作废的样品：明确无结果。
470		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
471			t.Fatalf("P1 应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
472		}
473	
474		// 已确认后作废的完整历史记录继续兼容。
475		p2, err := s.ListByPoint("P2")
476		if err != nil || len(p2) != 1 {
477			t.Fatalf("P2 列表: %+v err=%v", p2, err)
478		}
479		scv := p2[0]
480		if scv.Status != StatusVoided || !scv.Exceeded || len(scv.Results) != 1 {
481			t.Fatalf("已确认后作废的历史依据应保留: %+v", scv)
482		}
483		if r := scv.Results[0]; r.Item != openPH || r.Value != 9 || r.Limit != 8 ||
484			!r.LimitEffective.Equal(openEff()) || !r.Exceeded {
485			t.Fatalf("历史判定依据被改动: %+v", r)
486		}
487		if latest, ok, err := s.LatestResult("P2"); err != nil || ok {
488			t.Fatalf("作废样品不应作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
489		}
490		if _, err := s.Confirm("SCV"); !errors.Is(err, ErrVoided) {
491			t.Fatalf("已作废样品再确认应被拒绝，got %v", err)
492		}
493	}
494	
495	// 已确认后作废但历史依据缺项，同样不能读入：作废只取消有效资格，
496	// 不能让对不上的结论借“历史记录”名义混进台账。
497	func TestOpenVoidedAfterConfirmedMissingItemResult(t *testing.T) {
498		dir := t.TempDir()
499		writeDiskFile(t, dir, diskState{
500			Points: openPoints(),
501			Samples: map[string]*Sample{
502				"S1": {
503					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
504					Measurements: phTurbMeasurements(),
505					Status:       StatusVoided, VoidReason: "作废", Exceeded: true,
506					Results: []ItemResult{
507						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
508					},
509				},
510			},
511		})
512		assertOpenRejects(t, dir, "S1", openTurb, false)
513	}
514	
515	// 文件里出现空样品记录（JSON null）时不能崩溃，也要整次失败并按 map 编号指出。
516	func TestOpenNullSampleRecord(t *testing.T) {
517		dir := t.TempDir()
518		writeDiskFile(t, dir, diskState{
519			Points: openPoints(),
520			Samples: map[string]*Sample{
521				"S1": nil,
522			},
523		})
524		assertOpenRejects(t, dir, "S1", "", true)
525	}
526

