1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16		"unicode/utf8"
17	)
18	
19	// Status 表示样品所处的判定状态。
20	type Status string
21	
22	const (
23		// StatusPending 样品已录入，尚未确认判定结果。
24		StatusPending Status = "pending"
25		// StatusConfirmed 样品已确认，判定结果已保存。
26		StatusConfirmed Status = "confirmed"
27		// StatusVoided 样品已作废，保留记录但不能再确认。
28		StatusVoided Status = "voided"
29	)
30	
31	var (
32		ErrClosed             = errors.New("water: 数据存放已关闭")
33		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
34		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
35		ErrUnknownPoint       = errors.New("water: 采样点未登记")
36		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
37		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
38		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
39		ErrUnknownSample      = errors.New("water: 样品编号不存在")
40		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
41		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
42		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
43		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
44		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
45		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
46		ErrInvalidText        = errors.New("water: 采样点编号、名称、项目名、样品编号或作废原因不是合法的 UTF-8 文本")
47		ErrCorruptRecord      = errors.New("water: 本地数据中存在测量项目与逐项判定对应不上的已确认样品")
48	)
49	
50	// SamplingPoint 是按编号唯一登记的采样点。
51	type SamplingPoint struct {
52		ID   string `json:"id"`
53		Name string `json:"name"`
54	}
55	
56	// Limit 是某采样点某测量项目的一版数值上限。
57	type Limit struct {
58		PointID   string    `json:"pointId"`
59		Item      string    `json:"item"`
60		Value     float64   `json:"value"`
61		Effective time.Time `json:"effective"`
62	}
63	
64	// Measurement 是样品中一个项目的测量值。
65	type Measurement struct {
66		Item  string  `json:"item"`
67		Value float64 `json:"value"`
68	}
69	
70	// ItemResult 是确认后单个项目的判定结果。
71	type ItemResult struct {
72		Item           string    `json:"item"`
73		Value          float64   `json:"value"`
74		Limit          float64   `json:"limit"`
75		LimitEffective time.Time `json:"limitEffective"`
76		Exceeded       bool      `json:"exceeded"`
77	}
78	
79	// Sample 是一份从录入、确认到作废的样品记录。
80	type Sample struct {
81		ID           string        `json:"id"`
82		PointID      string        `json:"pointId"`
83		SampledAt    time.Time     `json:"sampledAt"`
84		Measurements []Measurement `json:"measurements"`
85		Status       Status        `json:"status"`
86		Results      []ItemResult  `json:"results,omitempty"`
87		Exceeded     bool          `json:"exceeded"`
88		VoidReason   string        `json:"voidReason,omitempty"`
89	}
90	
91	// diskState 是落盘的完整数据。
92	type diskState struct {
93		Points  map[string]SamplingPoint `json:"points"`
94		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
95		Samples map[string]*Sample       `json:"samples"`
96	}
97	
98	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
99	// 用单字符拼接成键时不同组合撞成同一组。
100	type limitGroup struct {
101		pointID string
102		item    string
103	}
104	
105	// Store 是绑定到某个本地目录的取样判定数据存放。
106	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
107	type Store struct {
108		mu      sync.Mutex
109		dir     string
110		file    string
111		closed  bool
112		points  map[string]SamplingPoint
113		limits  map[limitGroup][]Limit // 按生效时间升序
114		samples map[string]*Sample
115	}
116	
117	// Open 打开（必要时创建）dir 下的本地数据存放。
118	//
119	// 读入时会核对每份已保存结论的样品：已确认样品，以及已确认后作废、逐项
120	// 依据仍保留在 Results 中的样品，其原测量项目与逐项判定必须按项目名完整
121	// 一一对应——至少有一个测量项目；原测量或判定中同一项目不能出现两次；每个
122	// 测量项目必须且只能有一条判定，判定里也不能出现原测量没有的项目；对应
123	// 项目的判定测量值必须与原测量值一致（零是合法测量值，不会被当成缺项）。
124	// 两个列表排列顺序不同不影响对应，成功读入后测量与判定各自保留原顺序。
125	// 任一份样品对不上，整次打开以可被 errors.Is(err, ErrCorruptRecord) 识别的
126	// 错误失败，返回 nil 数据存放，错误信息点到具体样品编号与项目；不会静默
127	// 跳过问题样品、不会补出缺失判定、不会把它改成待判定，也不会改写原文件。
128	// 待判定样品没有判定记录、待判定后作废的样品没有历史依据，均属正常。
129	// 完整记录原样读入，已保存的上限、生效时间、逐项结论与整份超标标记保留，
130	// 不因后来新增或补录的限值而拒绝或重新计算。
131	func Open(dir string) (*Store, error) {
132		if strings.TrimSpace(dir) == "" {
133			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
134		}
135		if err := os.MkdirAll(dir, 0o755); err != nil {
136			return nil, err
137		}
138		s := &Store{
139			dir:     dir,
140			file:    filepath.Join(dir, "water-data.json"),
141			points:  map[string]SamplingPoint{},
142			limits:  map[limitGroup][]Limit{},
143			samples: map[string]*Sample{},
144		}
145		data, err := os.ReadFile(s.file)
146		if errors.Is(err, fs.ErrNotExist) {
147			return s, nil
148		}
149		if err != nil {
150			return nil, err
151		}
152		var st diskState
153		if err := json.Unmarshal(data, &st); err != nil {
154			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
155		}
156		if st.Points != nil {
157			s.points = st.Points
158		}
159		if st.Limits != nil {
160			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
161			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
162			// 让曾经被错误合并的组在重新打开时也能各自归位。
163			for _, versions := range st.Limits {
164				for _, lim := range versions {
165					g := limitGroup{pointID: lim.PointID, item: lim.Item}
166					s.limits[g] = append(s.limits[g], lim)
167				}
168			}
169			for g, versions := range s.limits {
170				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
171				s.limits[g] = versions
172			}
173		}
174		if st.Samples != nil {
175			// 已确认结论只能在逐项判定与原测量完整对应时读入：任一份已确认样品
176			// （含已确认后作废、仍保留历史依据的样品）对应不上，整次打开都失败，
177			// 不返回数据存放对象，也不静默跳过、补判定或回写原文件。
178			ids := make([]string, 0, len(st.Samples))
179			for id := range st.Samples {
180				ids = append(ids, id)
181			}
182			sort.Strings(ids)
183			for _, id := range ids {
184				if err := validateLoadedSample(id, st.Samples[id]); err != nil {
185					return nil, err
186				}
187			}
188			s.samples = st.Samples
189		}
190		return s, nil
191	}
192	
193	// validateLoadedSample 校验一份从本地文件读入、带有判定结论的样品记录：
194	// 已确认样品，以及已确认后作废、Results 中仍保留历史依据的样品，其原测量
195	// 项目与逐项判定必须按项目名一一对应——至少一个测量项目；原测量和判定中同一
196	// 项目都不能出现两次；每个测量项目必须且只能有一条判定记录，判定中也不能出现
197	// 原测量没有的项目；对应项目的判定测量值必须与原测量值逐位一致（零是合法
198	// 测量值，按 map 中是否存在该项目判断，不把零当成缺项）。项目按名称对应，
199	// 与两个列表的排列顺序无关。待判定样品与待判定后作废（没有历史依据）的样品
200	// 不带逐项判定，属于正常情况，不在此校验之列。key 是落盘 map 中的样品编号，
201	// 用于在记录本身残缺（如空记录）时仍能指出是哪份样品。
202	func validateLoadedSample(key string, smp *Sample) error {
203		if smp == nil {
204			return fmt.Errorf("%w: 样品 %s 的记录为空", ErrCorruptRecord, key)
205		}
206		id := smp.ID
207		if id == "" {
208			id = key
209		}
210		if smp.Status != StatusConfirmed && len(smp.Results) == 0 {
211			return nil
212		}
213		if len(smp.Measurements) == 0 {
214			return fmt.Errorf("%w: 样品 %s 没有测量项目", ErrCorruptRecord, id)
215		}
216		meas := make(map[string]float64, len(smp.Measurements))
217		for _, m := range smp.Measurements {
218			if _, ok := meas[m.Item]; ok {
219				return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, id, m.Item)
220			}
221			meas[m.Item] = m.Value
222		}
223		got := make(map[string]float64, len(smp.Results))
224		for _, r := range smp.Results {
225			if _, ok := got[r.Item]; ok {
226				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, id, r.Item)
227			}
228			got[r.Item] = r.Value
229		}
230		// 缺项或判定测量值与原测量不一致（按测量列表顺序报告，保持信息稳定）。
231		for _, m := range smp.Measurements {
232			rv, ok := got[m.Item]
233			if !ok {
234				return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, id, m.Item)
235			}
236			if rv != m.Value {
237				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
238					ErrCorruptRecord, id, m.Item, rv, m.Value)
239			}
240		}
241		// 判定中出现原测量没有的项目。
242		for _, r := range smp.Results {
243			if _, ok := meas[r.Item]; !ok {
244				return fmt.Errorf("%w: 样品 %s 的判定记录出现了原测量中没有的项目 %s",
245					ErrCorruptRecord, id, r.Item)
246			}
247		}
248		return nil
249	}
250	
251	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
252	func (s *Store) Close() error {
253		s.mu.Lock()
254		defer s.mu.Unlock()
255		if s.closed {
256			return nil
257		}
258		s.closed = true
259		return nil
260	}
261	
262	func clean(s string) string { return strings.TrimSpace(s) }
263	
264	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
265	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
266	func diskLimitKey(pointID, item string) string {
267		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
268	}
269	
270	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
271	
272	// invalidUTF8 报告文本是否无法作为合法 UTF-8 原样保存。必须在任何处理之前检查
273	// 提交的原始文本：落盘 JSON 会把非法字节（孤立的 0xFF、0xFE、不完整的多字节
274	// 序列等）静默替换成 U+FFFD，返回记录与保存内容会因此对不上，两个不同编号也
275	// 可能变成同一文本。真正的 U+FFFD（“�”）以及中文、U+0000 等都是合法字符，
276	// 不在拒绝之列；只在去首尾空白之外不做任何字符替换或归一化。
277	func invalidUTF8(s string) bool { return !utf8.ValidString(s) }
278	
279	func (s *Store) checkOpenLocked() error {
280		if s.closed {
281			return ErrClosed
282		}
283		return nil
284	}
285	
286	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
287	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
288	func (s *Store) persistLocked() error {
289		diskLimits := make(map[string][]Limit, len(s.limits))
290		for g, versions := range s.limits {
291			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
292		}
293		data, err := json.MarshalIndent(diskState{
294			Points:  s.points,
295			Limits:  diskLimits,
296			Samples: s.samples,
297		}, "", "  ")
298		if err != nil {
299			return err
300		}
301		tmp := s.file + ".tmp"
302		if err := os.WriteFile(tmp, data, 0o644); err != nil {
303			return err
304		}
305		return os.Rename(tmp, s.file)
306	}
307	
308	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
309	// 保存和比较均使用处理后的文本；重复编号拒绝。
310	// 编号和名称必须都是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE 字节
311	// 或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
312	// 拒绝，不占用编号、不改动任何已有采样点；即使另一项为空白，或编号已登记而
313	// 这次名称含非法字节，也报告编码错误。真正的 U+FFFD（“�”）、中文和文本内部
314	// 的 U+0000 仍是合法字符。
315	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
316		s.mu.Lock()
317		defer s.mu.Unlock()
318		if err := s.checkOpenLocked(); err != nil {
319			return SamplingPoint{}, err
320		}
321		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
322		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
323		// 两个不同编号（如末尾分别带孤立 0xFF、0xFE）还可能保存成同一编号；
324		// 只有整次拒绝才能保证采样点身份在保存前后一致。
325		if invalidUTF8(id) || invalidUTF8(name) {
326			return SamplingPoint{}, ErrInvalidText
327		}
328		id, name = clean(id), clean(name)
329		if id == "" || name == "" {
330			return SamplingPoint{}, ErrEmptyField
331		}
332		if _, ok := s.points[id]; ok {
333			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
334		}
335		p := SamplingPoint{ID: id, Name: name}
336		s.points[id] = p
337		if err := s.persistLocked(); err != nil {
338			delete(s.points, id)
339			return SamplingPoint{}, err
340		}
341		return p, nil
342	}
343	
344	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
345	// 采样点编号和项目名必须是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE
346	// 字节或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
347	// 拒绝，不新增版本、不占用生效时间；真正的 U+FFFD（“�”）、中文和文本内部的
348	// U+0000 仍是合法字符。即使同次请求还存在采样点未登记、数值不是有限数或
349	// 生效时间缺失的问题，也报告文本编码错误。
350	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
351	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
352		s.mu.Lock()
353		defer s.mu.Unlock()
354		if err := s.checkOpenLocked(); err != nil {
355			return Limit{}, err
356		}
357		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
358		// 静默替换成 U+FFFD，登记“成功”后保存的项目名就会与填写内容对不上，
359		// 限值也不再属于实际填写的采样点和项目；只有整次拒绝才能保证一致。
360		if invalidUTF8(pointID) || invalidUTF8(item) {
361			return Limit{}, ErrInvalidText
362		}
363		pointID, item = clean(pointID), clean(item)
364		if pointID == "" || item == "" {
365			return Limit{}, ErrEmptyField
366		}
367		if _, ok := s.points[pointID]; !ok {
368			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
369		}
370		if !finite(value) {
371			return Limit{}, ErrInvalidValue
372		}
373		if effective.IsZero() {
374			return Limit{}, ErrInvalidTime
375		}
376		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
377		g := limitGroup{pointID: pointID, item: item}
378		versions := s.limits[g]
379		for _, v := range versions {
380			if v.Effective.Equal(lim.Effective) {
381				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
382			}
383		}
384		old := s.limits[g]
385		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
386		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
387		versions = make([]Limit, len(old)+1)
388		copy(versions, old)
389		versions[len(old)] = lim
390		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
391		s.limits[g] = versions
392		if err := s.persistLocked(); err != nil {
393			s.limits[g] = old
394			return Limit{}, err
395		}
396		return lim, nil
397	}
398	
399	// SubmitSample 录入一份样品，初始为待判定状态。
400	// 样品编号、采样点编号和每个项目名必须是合法的 UTF-8 文本：任一字段含孤立的
401	// 0xFF、0xFE 字节或不完整的多字节序列等无法原样保存的内容时，整份提交以
402	// ErrInvalidText 拒绝，不留部分记录，也不占用编号；真正的 U+FFFD（“�”）
403	// 仍是合法字符。再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
404	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
405	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
406		s.mu.Lock()
407		defer s.mu.Unlock()
408		if err := s.checkOpenLocked(); err != nil {
409			return Sample{}, err
410		}
411		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
412		// 静默替换成 U+FFFD，只有整份拒绝才能保证返回记录、按点查看与保存数据一致。
413		// 即使编号已被已有样品占用、非法项目排在最后，或提交同时存在其它内容问题，
414		// 也必须报告编码问题：不能归为未知采样点、项目重复或同编号冲突，更不能走
415		// 重复录入成功的分支。
416		if invalidUTF8(id) || invalidUTF8(pointID) {
417			return Sample{}, ErrInvalidText
418		}
419		for _, m := range measurements {
420			if invalidUTF8(m.Item) {
421				return Sample{}, ErrInvalidText
422			}
423		}
424		id, pointID = clean(id), clean(pointID)
425		if id == "" || pointID == "" {
426			return Sample{}, ErrEmptyField
427		}
428		if sampledAt.IsZero() {
429			return Sample{}, ErrInvalidTime
430		}
431		if len(measurements) == 0 {
432			return Sample{}, ErrNoMeasurements
433		}
434		ms := make([]Measurement, len(measurements))
435		seen := make(map[string]float64, len(measurements))
436		for i, m := range measurements {
437			item := clean(m.Item)
438			if item == "" {
439				return Sample{}, ErrEmptyField
440			}
441			if !finite(m.Value) {
442				return Sample{}, ErrInvalidValue
443			}
444			if _, dup := seen[item]; dup {
445				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
446			}
447			seen[item] = m.Value
448			ms[i] = Measurement{Item: item, Value: m.Value}
449		}
450		sampledAt = sampledAt.UTC()
451	
452		if existing, ok := s.samples[id]; ok {
453			if sameSampleContent(existing, pointID, sampledAt, seen) {
454				return copySample(existing), nil
455			}
456			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
457		}
458		if _, ok := s.points[pointID]; !ok {
459			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
460		}
461		smp := &Sample{
462			ID:           id,
463			PointID:      pointID,
464			SampledAt:    sampledAt,
465			Measurements: ms,
466			Status:       StatusPending,
467		}
468		s.samples[id] = smp
469		if err := s.persistLocked(); err != nil {
470			delete(s.samples, id)
471			return Sample{}, err
472		}
473		return copySample(smp), nil
474	}
475	
476	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
477		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
478			return false
479		}
480		for _, m := range s.Measurements {
481			v, ok := ms[m.Item]
482			if !ok || v != m.Value {
483				return false
484			}
485		}
486		return true
487	}
488	
489	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
490	// 测量值大于上限才超标，任一项目超标则整份样品超标。
491	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
492	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
493	func (s *Store) Confirm(id string) (Sample, error) {
494		s.mu.Lock()
495		defer s.mu.Unlock()
496		if err := s.checkOpenLocked(); err != nil {
497			return Sample{}, err
498		}
499		id = clean(id)
500		if id == "" {
501			return Sample{}, ErrEmptyField
502		}
503		smp, ok := s.samples[id]
504		if !ok {
505			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
506		}
507		switch smp.Status {
508		case StatusVoided:
509			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
510		case StatusConfirmed:
511			return copySample(smp), nil
512		}
513	
514		results := make([]ItemResult, 0, len(smp.Measurements))
515		exceeded := false
516		for _, m := range smp.Measurements {
517			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
518			if !ok {
519				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
520			}
521			ex := m.Value > lim.Value
522			if ex {
523				exceeded = true
524			}
525			results = append(results, ItemResult{
526				Item:           m.Item,
527				Value:          m.Value,
528				Limit:          lim.Value,
529				LimitEffective: lim.Effective,
530				Exceeded:       ex,
531			})
532		}
533		smp.Results = results
534		smp.Exceeded = exceeded
535		smp.Status = StatusConfirmed
536		if err := s.persistLocked(); err != nil {
537			smp.Results = nil
538			smp.Exceeded = false
539			smp.Status = StatusPending
540			return Sample{}, err
541		}
542		return copySample(smp), nil
543	}
544	
545	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
546	// 采样时间恰好等于生效时间时使用该版新值。
547	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
548		best := -1
549		for i, v := range versions {
550			if v.Effective.After(at) {
551				break
552			}
553			best = i
554		}
555		if best < 0 {
556			return Limit{}, false
557		}
558		return versions[best], true
559	}
560	
561	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
562	// 作废原因必须是合法的 UTF-8 文本：原始原因含孤立的 0xFF、0xFE 字节或不完整
563	// 的多字节序列等无法原样保存的内容时，本次作废整体以 ErrInvalidText 拒绝，
564	// 返回空样品，不删除或替换任何字节、不改动样品状态与已有原因；即使样品编号
565	// 不存在，或样品已作废而这次原因与原原因不同，也报告文本编码错误，而不是
566	// 样品不存在或原因冲突（数据存放已关闭时仍返回 ErrClosed）。真正的 U+FFFD
567	// （“�”）、中文、表情和文本内部的 U+0000 仍是合法字符。作废后保留测量、原因
568	// 和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
569	func (s *Store) Void(id, reason string) (Sample, error) {
570		s.mu.Lock()
571		defer s.mu.Unlock()
572		if err := s.checkOpenLocked(); err != nil {
573			return Sample{}, err
574		}
575		// 在去首尾空白、查找样品和比对原因等任何处理之前检查原始原因：落盘 JSON
576		// 会把非法 UTF-8 静默替换成 U+FFFD，作废“成功”后当场返回的原因仍带原始
577		// 字节，保存与重开后却变成替换字符，同一记录前后对不上，再次提交原原因
578		// 还会被误判成原因冲突；只有整次拒绝才能保证原因在保存前后一致。
579		if invalidUTF8(reason) {
580			return Sample{}, ErrInvalidText
581		}
582		id, reason = clean(id), clean(reason)
583		if id == "" || reason == "" {
584			return Sample{}, ErrEmptyField
585		}
586		smp, ok := s.samples[id]
587		if !ok {
588			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
589		}
590		if smp.Status == StatusVoided {
591			if smp.VoidReason == reason {
592				return copySample(smp), nil
593			}
594			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
595		}
596		oldStatus := smp.Status
597		smp.Status = StatusVoided
598		smp.VoidReason = reason
599		if err := s.persistLocked(); err != nil {
600			smp.Status = oldStatus
601			smp.VoidReason = ""
602			return Sample{}, err
603		}
604		return copySample(smp), nil
605	}
606	
607	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
608	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
609		s.mu.Lock()
610		defer s.mu.Unlock()
611		if err := s.checkOpenLocked(); err != nil {
612			return nil, err
613		}
614		return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
615	}
616	
617	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
618	// 没有已确认且未作废的样品时 ok 为 false。
619	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
620		s.mu.Lock()
621		defer s.mu.Unlock()
622		if err := s.checkOpenLocked(); err != nil {
623			return Sample{}, false, err
624		}
625		list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
626			return smp.Status == StatusConfirmed
627		})
628		if len(list) == 0 {
629			return Sample{}, false, nil
630		}
631		return list[0], true, nil
632	}
633	
634	// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
635	// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
636	// 调用方须已持有锁；pointID 须已做首尾空白处理。
637	func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
638		var list []Sample
639		for _, smp := range s.samples {
640			if smp.PointID == pointID && keep(smp) {
641				list = append(list, copySample(smp))
642			}
643		}
644		sortSamples(list)
645		return list
646	}
647	
648	func sortSamples(list []Sample) {
649		sort.Slice(list, func(i, j int) bool {
650			a, b := list[i], list[j]
651			if !a.SampledAt.Equal(b.SampledAt) {
652				return a.SampledAt.After(b.SampledAt)
653			}
654			return a.ID < b.ID
655		})
656	}
657	
658	func copySample(s *Sample) Sample {
659		c := *s
660		c.Measurements = append([]Measurement(nil), s.Measurements...)
661		c.Results = append([]ItemResult(nil), s.Results...)
662		return c
663	}
664

