514	func TestConfirm(t *testing.T) {
515		s, _ := open(t)
516		mustPoint(t, s, "P1", "取水口")
517		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
518		mustLimit(t, s, "P1", "pH", 7.0, at(10, 0))
519		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
520	
521		// 缺一个项目的适用上限：拒绝，保持待判定，不留部分结论
522		mustSample(t, s, "S1", "P1", at(12, 0),
523			Measurement{Item: "pH", Value: 7.5}, Measurement{Item: "SS", Value: 10})
524		if _, err := s.Confirm("S1"); !errors.Is(err, ErrMissingLimit) {
525			t.Fatalf("missing limit should reject, got %v", err)
526		}
527		_, ok, err := s.LatestResult("P1")
528		if err != nil || ok {
529			t.Fatalf("no confirmed sample expected")
530		}
531		list, _ := s.ListByPoint("P1")
532		if len(list) != 1 || list[0].Status != StatusPending || list[0].Results != nil {
533			t.Fatalf("rejected confirm must leave sample pending without partial results: %+v", list)
534		}
535	
536		// 补齐限值后可再次确认
537		mustLimit(t, s, "P1", "SS", 15.0, at(1, 0))
538		smp1, err := s.Confirm("S1")
539		if err != nil {
540			t.Fatalf("Confirm after backfill: %v", err)
541		}
542		if smp1.Status != StatusConfirmed || !smp1.Exceeded {
543			t.Fatalf("expected confirmed & exceeded, got %+v", smp1)
544		}
545		// pH 取不晚于采样时间的最近一版（7.0@09-10），7.5 超标；SS 10 ≤ 15 达标
546		if smp1.Results[0].Limit != 7.0 || !smp1.Results[0].Exceeded {
547			t.Fatalf("pH result wrong: %+v", smp1.Results[0])
548		}
549		if smp1.Results[1].Limit != 15.0 || smp1.Results[1].Exceeded {
550			t.Fatalf("SS result wrong: %+v", smp1.Results[1])
551		}
552	
553		// 采样时间恰好等于生效时间时使用新值
554		mustSample(t, s, "S2", "P1", at(10, 0), Measurement{Item: "pH", Value: 7.5})
555		smp2, err := s.Confirm("S2")
556		if err != nil {
557			t.Fatalf("Confirm S2: %v", err)
558		}
559		if smp2.Results[0].Limit != 7.0 || !smp2.Results[0].LimitEffective.Equal(at(10, 0)) {
560			t.Fatalf("boundary effective time should use new value, got %+v", smp2.Results[0])
561		}
562		if !smp2.Exceeded {
563			t.Fatalf("7.5 > 7.0 should exceed")
564		}
565	
566		// 等于上限算达标
567		mustSample(t, s, "S3", "P1", at(11, 0), Measurement{Item: "pH", Value: 7.0})
568		smp3, _ := s.Confirm("S3")
569		if smp3.Exceeded || smp3.Results[0].Exceeded {
570			t.Fatalf("equal to limit should pass, got %+v", smp3.Results[0])
571		}
572	
573		// 重复确认直接返回已保存结果；之后补录限值不改变已确认结果
574		mustLimit(t, s, "P1", "pH", 100.0, at(10, 12))
575		again, err := s.Confirm("S2")
576		if err != nil {
577			t.Fatalf("re-confirm: %v", err)
578		}
579		if again.Results[0].Limit != 7.0 || !again.Exceeded {
580			t.Fatalf("confirmed result must not change, got %+v", again.Results[0])
581		}
582	
583		if _, err := s.Confirm("nope"); !errors.Is(err, ErrUnknownSample) {
584			t.Fatalf("unknown sample, got %v", err)
585		}
586	}
