588	// 所有项目都能完成判定、但本地保存结果失败时，本次确认必须整体失败：
589	// 已算出的逐项结果与整份样品的超标标记都不能生效，样品保持待判定，
590	// 采样点上一份已确认样品仍是最近有效结果；保存条件恢复后可重新确认，
591	// 按采样当时适用的限值完整保存逐项判定（一项超标、一项等于上限）。
592	func TestConfirmPersistFailure(t *testing.T) {
593		s, dir := open(t)
594		mustPoint(t, s, "P1", "取水口")
595		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
596		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
597	
598		resultByItem := func(rs []ItemResult) map[string]ItemResult {
599			m := make(map[string]ItemResult, len(rs))
600			for _, r := range rs {
601				m[r.Item] = r
602			}
603			return m
604		}
605		find := func(list []Sample, id string) Sample {
606			t.Helper()
607			for _, smp := range list {
608				if smp.ID == id {
609					return smp
610				}
611			}
612			t.Fatalf("sample %q missing from list %+v", id, list)
613			return Sample{}
614		}
615	
616		// 采样时间较早、正常保存的已确认样品：pH 7 ≤ 8，达标
617		mustSample(t, s, "S1", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
618		conf1, err := s.Confirm("S1")
619		if err != nil || conf1.Status != StatusConfirmed || conf1.Exceeded {
620			t.Fatalf("Confirm S1 setup: %+v err=%v", conf1, err)
621		}
622	
623		// 更晚的待判定样品：两个项目采样时均有适用上限，pH 超上限，COD 恰好等于上限
624		mustSample(t, s, "S2", "P1", at(10, 0),
625			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
626		// 对照样品：缺少适用上限，用来证明本检查区分判定错误与保存错误
627		mustSample(t, s, "S3", "P1", at(2, 0), Measurement{Item: "SS", Value: 1})
628	
629		// 只让确认结果的保存失败：采样点、限值和样品准备此前均已成功落盘。
630		// 占用临时文件路径为目录后，原子写的 WriteFile 必然失败，不依赖目录权限。
631		tmp := filepath.Join(dir, "water-data.json.tmp")
632		if err := os.Mkdir(tmp, 0o755); err != nil {
633			t.Fatalf("block persist: %v", err)
634		}
635	
636		// 同样无法保存的条件下，缺上限在判定阶段即以 ErrMissingLimit 拒绝，
637		// 根本走不到保存；S2 的失败必须是与之不同的保存错误。
638		if _, err := s.Confirm("S3"); !errors.Is(err, ErrMissingLimit) {
639			t.Fatalf("missing limit should be a judgment error, got %v", err)
640		}
641		got, err := s.Confirm("S2")
642		if err == nil {
643			t.Fatal("Confirm should fail when results cannot be saved")
644		}
645		if errors.Is(err, ErrMissingLimit) {
646			t.Fatalf("save failure must not be reported as missing limit: %v", err)
647		}
648		if got.ID != "" || got.Status == StatusConfirmed {
649			t.Fatalf("failed save must not return a confirmed sample: %+v", got)
650		}
651	
652		// 按采样点查看：原采样时间、项目和测量值保持，状态待判定，
653		// 没有逐项判定结果，整份样品也不能带上失败尝试算出的超标标记。
654		list, err := s.ListByPoint("P1")
655		if err != nil {
656			t.Fatalf("ListByPoint after failed save: %v", err)
657		}
658		if len(list) != 3 {
659			t.Fatalf("list should keep all three samples, got %+v", list)
660		}
661		failed := find(list, "S2")
662		if failed.Status != StatusPending || failed.Exceeded || failed.Results != nil {
663			t.Fatalf("failed confirm must leave pending sample without results: %+v", failed)
664		}
665		if !failed.SampledAt.Equal(at(10, 0)) || len(failed.Measurements) != 2 {
666			t.Fatalf("sampled time and measurements changed: %+v", failed)
667		}
668		values := map[string]float64{}
669		for _, m := range failed.Measurements {
670			values[m.Item] = m.Value
671		}
672		if values["pH"] != 9 || values["COD"] != 30 {
673			t.Fatalf("measurements changed: %+v", failed.Measurements)
674		}
675		if s3 := find(list, "S3"); s3.Status != StatusPending || s3.Results != nil {
676			t.Fatalf("S3 should stay pending without results: %+v", s3)
677		}
678	
679		// 同一份已打开的数据存放中，最近有效结果仍是较早的 S1，
680		// 结论与所用限值保持原样，不能被采样更晚的失败尝试顶替。
681		latest, ok, err := s.LatestResult("P1")
682		if err != nil || !ok || latest.ID != "S1" {
683			t.Fatalf("latest valid result should stay S1, got %+v ok=%v err=%v", latest, ok, err)
684		}
685		if latest.Exceeded || len(latest.Results) != 1 {
686			t.Fatalf("S1 conclusion changed: %+v", latest)
687		}
688		r1 := latest.Results[0]
689		if r1.Item != "pH" || r1.Value != 7 || r1.Limit != 8.0 || !r1.LimitEffective.Equal(at(1, 0)) || r1.Exceeded {
690			t.Fatalf("S1 result and limit must remain intact: %+v", r1)
691		}
692	
693		// 恢复正常保存条件
694		if err := os.Remove(tmp); err != nil {
695			t.Fatalf("restore persist: %v", err)
696		}
697		// 采样时间之后才生效的新版上限不能影响按采样当时适用限值的重新判定
698		mustLimit(t, s, "P1", "pH", 9.5, at(15, 0))
699	
700		// 重新确认：不能被当成已确认而直接返回失败尝试的状态，必须重新判定并成功保存
701		conf2, err := s.Confirm("S2")
702		if err != nil {
703			t.Fatalf("retry Confirm after save restored: %v", err)
704		}
705		checkSaved := func(smp Sample, label string) {
706			t.Helper()
707			if smp.Status != StatusConfirmed || !smp.SampledAt.Equal(at(10, 0)) || !smp.Exceeded || len(smp.Results) != 2 {
708				t.Fatalf("%s: confirmed sample wrong: %+v", label, smp)
709			}
710			rs := resultByItem(smp.Results)
711			ph, cod := rs["pH"], rs["COD"]
712			if ph.Value != 9 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || !ph.Exceeded {
713				t.Fatalf("%s: pH should be 9 > 8@09-01 exceeded, got %+v", label, ph)
714			}
715			if cod.Value != 30 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
716				t.Fatalf("%s: COD 30 == limit 30@09-01 should pass, got %+v", label, cod)
717			}
718		}
719		checkSaved(conf2, "retry result")
720	
721		// 重复确认返回已保存结果
722		again, err := s.Confirm("S2")
723		if err != nil {
724			t.Fatalf("re-confirm S2: %v", err)
725		}
726		checkSaved(again, "re-confirm")
727		// 原样品的结论与所用限值保持原样，不受新限值影响
728		keep1, err := s.Confirm("S1")
729		if err != nil || keep1.Exceeded || keep1.Results[0].Limit != 8.0 || !keep1.Results[0].LimitEffective.Equal(at(1, 0)) {
730			t.Fatalf("S1 must remain confirmed as saved, got %+v err=%v", keep1, err)
731		}
732	
733		// 按采样点查看的记录与最近有效结果一致
734		list2, err := s.ListByPoint("P1")
735		if err != nil {
736			t.Fatalf("ListByPoint after recovery: %v", err)
737		}
738		saved := find(list2, "S2")
739		latest2, ok, err := s.LatestResult("P1")
740		if err != nil || !ok || latest2.ID != "S2" {
741			t.Fatalf("later S2 should now be the latest valid result, got %+v ok=%v err=%v", latest2, ok, err)
742		}
743		checkSaved(saved, "list")
744		checkSaved(latest2, "latest")
745		if s3 := find(list2, "S3"); s3.Status != StatusPending || s3.Results != nil || s3.Exceeded {
746			t.Fatalf("S3 should still be pending with no failure marker: %+v", s3)
747		}
748	
749		// 重新打开同一数据存放：成功保存的结果落盘，失败尝试不留任何痕迹
750		if err := s.Close(); err != nil {
751			t.Fatalf("Close: %v", err)
752		}
753		s2, err := Open(dir)
754		if err != nil {
755			t.Fatalf("reopen: %v", err)
756		}
757		defer s2.Close()
758		list3, err := s2.ListByPoint("P1")
759		if err != nil {
760			t.Fatalf("reopened ListByPoint: %v", err)
761		}
762		latest3, ok, err := s2.LatestResult("P1")
763		if err != nil || !ok {
764			t.Fatalf("reopened latest result: %+v ok=%v err=%v", latest3, ok, err)
765		}
766		checkSaved(find(list3, "S2"), "reopened list")
767		checkSaved(latest3, "reopened latest")
768		if r := find(list3, "S1"); r.Status != StatusConfirmed || r.Exceeded || r.Results[0].Limit != 8.0 {
769			t.Fatalf("reopened S1 changed: %+v", r)
770		}
771		if r := find(list3, "S3"); r.Status != StatusPending || r.Results != nil {
772			t.Fatalf("reopened S3 should stay pending: %+v", r)
773		}
774	}
