// 待判定的损坏样品与其他完整样品同处一个文件：不能只跳过它继续打开，
// 整次失败、无可用存放，完整样品也读不到。
func TestOpenPendingDuplicateRejectsWholeFile(t *testing.T) {
	dir := t.TempDir()
	writeDiskFile(t, dir, diskState{
